// FindGame retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindGame(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*Game, error) {
	if len(cols) == 0 {
		return Games.Query(
			sm.Where(Games.Columns.ID.EQ(sqlite.Arg(IDPK))),
		).One(ctx, exec)
	}

	return Games.Query(
		sm.Where(Games.Columns.ID.EQ(sqlite.Arg(IDPK))),
		sm.Columns(Games.Columns.Only(cols...)),
	).One(ctx, exec)
}

// GameExists checks the presence of a single record by primary key
func GameExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return Games.Query(
		sm.Where(Games.Columns.ID.EQ(sqlite.Arg(IDPK))),
	).Exists(ctx, exec)
}

// AfterQueryHook is called after Game is retrieved from the database
func (o *Game) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Games.AfterSelectHooks.RunHooks(ctx, exec, GameSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = Games.AfterInsertHooks.RunHooks(ctx, exec, GameSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = Games.AfterUpdateHooks.RunHooks(ctx, exec, GameSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = Games.AfterDeleteHooks.RunHooks(ctx, exec, GameSlice{o})

	}

	return err
}

// primaryKeyVals returns the primary key values of the Game
func (o *Game) primaryKeyVals() bob.Expression {
	return sqlite.Arg(o.ID)
}

func (o *Game) pkEQ() dialect.Expression {
	return sqlite.Quote("game", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the Game
func (o *Game) Update(ctx context.Context, exec bob.Executor, s *GameSetter) error {
	v, err := Games.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

// Delete deletes a single Game record with an executor
func (o *Game) Delete(ctx context.Context, exec bob.Executor) error {
	_, err := Games.Delete(dm.Where(o.pkEQ())).Exec(ctx, exec)
	return err
}

// Reload refreshes the Game using the executor
func (o *Game) Reload(ctx context.Context, exec bob.Executor) error {
	o2, err := Games.Query(
		sm.Where(Games.Columns.ID.EQ(sqlite.Arg(o.ID))),
	).One(ctx, exec)
	if err != nil {
		return err
	}
	o2.R = o.R
	*o = *o2

	return nil
}

// AfterQueryHook is called after GameSlice is retrieved from the database
func (o GameSlice) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Games.AfterSelectHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeInsert:
		ctx, err = Games.AfterInsertHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeUpdate:
		ctx, err = Games.AfterUpdateHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeDelete:
		ctx, err = Games.AfterDeleteHooks.RunHooks(ctx, exec, o)

	}

	return err
}

func (o GameSlice) pkIN() dialect.Expression {
	if len(o) == 0 {
		return sqlite.Raw("NULL")
	}

	return sqlite.Quote("game", "id").In(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		pkPairs := make([]bob.Expression, len(o))
		for i, row := range o {
			pkPairs[i] = row.primaryKeyVals()
		}
		return bob.ExpressSlice(ctx, w, d, start, pkPairs, "", ", ", "")
	}))
}

// copyMatchingRows finds models in the given slice that have the same primary key
// then it first copies the existing relationships from the old model to the new model
// and then replaces the old model in the slice with the new model
func (o GameSlice) copyMatchingRows(from ...*Game) {
	for i, old := range o {
		for _, new := range from {
			if new.ID != old.ID {
				continue
			}
			new.R = old.R
			o[i] = new
			break
		}
	}
}

// UpdateMod modifies an update query with "WHERE primary_key IN (o...)"
func (o GameSlice) UpdateMod() bob.Mod[*dialect.UpdateQuery] {
	return bob.ModFunc[*dialect.UpdateQuery](func(q *dialect.UpdateQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Games.BeforeUpdateHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Game:
				o.copyMatchingRows(retrieved)
			case []*Game:
				o.copyMatchingRows(retrieved...)
			case GameSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Game or a slice of Game
				// then run the AfterUpdateHooks on the slice
				_, err = Games.AfterUpdateHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// DeleteMod modifies an delete query with "WHERE primary_key IN (o...)"
func (o GameSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Games.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Game:
				o.copyMatchingRows(retrieved)
			case []*Game:
				o.copyMatchingRows(retrieved...)
			case GameSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Game or a slice of Game
				// then run the AfterDeleteHooks on the slice
				_, err = Games.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

func (o GameSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals GameSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Games.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o GameSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Games.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o GameSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := Games.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

// GameServers starts a query for related objects on game_server
func (o *Game) GameServers(mods ...bob.Mod[*dialect.SelectQuery]) GameServersQuery {
	return GameServers.Query(append(mods,
		sm.Where(GameServers.Columns.GameID.EQ(sqlite.Arg(o.ID))),
	)...)
}

func (os GameSlice) GameServers(mods ...bob.Mod[*dialect.SelectQuery]) GameServersQuery {
	PKArgSlice := make([]bob.Expression, len(os))
	for i, o := range os {
		PKArgSlice[i] = sqlite.ArgGroup(o.ID)
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	return GameServers.Query(append(mods,
		sm.Where(sqlite.Group(GameServers.Columns.GameID).OP("IN", PKArgExpr)),
	)...)
}

func insertGameGameServers0(ctx context.Context, exec bob.Executor, gameServers1 []*GameServerSetter, game0 *Game) (GameServerSlice, error) {
	for i := range gameServers1 {
		gameServers1[i].GameID = omit.From(game0.ID)
	}

	ret, err := GameServers.Insert(bob.ToMods(gameServers1...)).All(ctx, exec)
	if err != nil {
		return ret, fmt.Errorf("insertGameGameServers0: %w", err)
	}

	return ret, nil
}

func attachGameGameServers0(ctx context.Context, exec bob.Executor, count int, gameServers1 GameServerSlice, game0 *Game) (GameServerSlice, error) {
	setter := &GameServerSetter{
		GameID: omit.From(game0.ID),
	}

	err := gameServers1.UpdateAll(ctx, exec, *setter)
	if err != nil {
		return nil, fmt.Errorf("attachGameGameServers0: %w", err)
	}

	return gameServers1, nil
}

func (game0 *Game) InsertGameServers(ctx context.Context, exec bob.Executor, related ...*GameServerSetter) error {
	if len(related) == 0 {
		return nil
	}

	var err error

	gameServers1, err := insertGameGameServers0(ctx, exec, related, game0)
	if err != nil {
		return err
	}

	game0.R.GameServers = append(game0.R.GameServers, gameServers1...)

	for _, rel := range gameServers1 {
		rel.R.Game = game0
		rel.R.Loaded.Game = true
	}
	return nil
}

func (game0 *Game) AttachGameServers(ctx context.Context, exec bob.Executor, related ...*GameServer) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	gameServers1 := GameServerSlice(related)

	_, err = attachGameGameServers0(ctx, exec, len(related), gameServers1, game0)
	if err != nil {
		return err
	}

	game0.R.GameServers = append(game0.R.GameServers, gameServers1...)

	for _, rel := range related {
		rel.R.Game = game0
		rel.R.Loaded.Game = true
	}

	return nil
}

