func (o *Game) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "GameServers":
		rels, ok := retrieved.(GameServerSlice)
		if !ok {
			return fmt.Errorf("game cannot load %T as %q", retrieved, name)
		}

		o.R.GameServers = rels
		o.R.Loaded.GameServers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Game = o
				rel.R.Loaded.Game = true
			}
		}
		return nil
	default:
		return fmt.Errorf("game has no relationship %q", name)
	}
}

